/**
 * ELMO Phase 4.0.1 — Standardized Workforce Artifact Service (WorkforceArtifactService)
 *
 * Governs structured, non-conversational work products generated by AI workers:
 * - Research Reports, Analytics Reports, Strategy Plans, Marketing Plans, Copy Packages,
 *   Sales Analyses, Code Artifacts, Automation Workflows, Support Cases, Operations Plans
 * - Formal lifecycle: Create -> Validate -> Verify -> Store -> Handoff / Return
 * - Version provenance tracking (v1 -> revision -> v2) without silent overwrites
 * - Strict multi-tenant organization isolation (RLS)
 */

import {
  WorkforceArtifact,
  ArtifactType,
  ArtifactStatus,
} from "./types/agentic.types";

export interface CreateArtifactParams {
  artifactType: ArtifactType;
  title: string;
  description: string;
  sourceWorker: string;
  sourceTask: string;
  organizationId: string;
  content: string;
  status?: ArtifactStatus;
  structuredData?: Record<string, unknown>;
  evidence?: string[];
  assumptions?: string[];
  verificationChecks?: string[];
}

export interface ReviseArtifactParams {
  artifactId: string;
  organizationId: string;
  sourceWorker: string;
  sourceTask: string;
  title?: string;
  description?: string;
  content: string;
  structuredData?: Record<string, unknown>;
  evidence?: string[];
  assumptions?: string[];
}

export class WorkforceArtifactService {
  private static instance: WorkforceArtifactService;

  // Stored artifacts: artifactId -> WorkforceArtifact
  private artifacts: Map<string, WorkforceArtifact> = new Map();

  // Version lineage: rootArtifactId -> WorkforceArtifact[] (in chronological order)
  private versions: Map<string, WorkforceArtifact[]> = new Map();

  private constructor() {}

  public static getInstance(): WorkforceArtifactService {
    if (!WorkforceArtifactService.instance) {
      WorkforceArtifactService.instance = new WorkforceArtifactService();
    }
    return WorkforceArtifactService.instance;
  }

  public static resetInstance(): void {
    WorkforceArtifactService.instance = undefined as any;
  }

  public reset(): void {
    this.artifacts.clear();
    this.versions.clear();
  }

  /**
   * Creates a new governed workforce artifact (Version 1).
   */
  public createArtifact(params: CreateArtifactParams): WorkforceArtifact {
    if (!params.organizationId) {
      throw new Error("Cannot create artifact without organizationId. Tenant isolation is mandatory.");
    }
    if (!params.title || !params.content) {
      throw new Error("Artifact requires title and content.");
    }

    const artifactId = `art-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
    const now = Date.now();

    const artifact: WorkforceArtifact = {
      artifactId,
      artifactType: params.artifactType,
      title: params.title,
      description: params.description || "",
      sourceWorker: params.sourceWorker,
      sourceTask: params.sourceTask,
      organizationId: params.organizationId,
      version: 1,
      status: params.status || "DRAFT",
      content: params.content,
      structuredData: params.structuredData || {},
      evidence: params.evidence || [],
      assumptions: params.assumptions || [],
      verification: params.verificationChecks
        ? {
            verified: false,
            verifier: "UNVERIFIED",
            timestamp: now,
            checks: params.verificationChecks,
          }
        : undefined,
      createdAt: now,
      updatedAt: now,
    };

    this.artifacts.set(artifactId, artifact);
    this.versions.set(artifactId, [{ ...artifact }]);

    return artifact;
  }

  /**
   * Revises an existing artifact, producing an immutable new version (e.g. v1 -> v2)
   * while preserving historical provenance.
   */
  public reviseArtifact(params: ReviseArtifactParams): WorkforceArtifact {
    const existing = this.getArtifact(params.artifactId, params.organizationId);
    if (!existing) {
      throw new Error(`Artifact "${params.artifactId}" not found or unauthorized for organization "${params.organizationId}".`);
    }

    // Mark previous as superseded in-place
    existing.status = "SUPERSEDED";
    existing.updatedAt = Date.now();

    const newArtifactId = `art-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
    const newVersionNumber = existing.version + 1;
    const now = Date.now();

    const newArtifact: WorkforceArtifact = {
      artifactId: newArtifactId,
      artifactType: existing.artifactType,
      title: params.title || existing.title,
      description: params.description || existing.description,
      sourceWorker: params.sourceWorker,
      sourceTask: params.sourceTask,
      organizationId: params.organizationId,
      version: newVersionNumber,
      status: "SUBMITTED",
      content: params.content,
      structuredData: params.structuredData || existing.structuredData,
      evidence: params.evidence || existing.evidence,
      assumptions: params.assumptions || existing.assumptions,
      verification: {
        verified: false,
        verifier: "UNVERIFIED",
        timestamp: now,
        checks: [],
      },
      createdAt: now,
      updatedAt: now,
      previousVersionId: existing.artifactId,
    };

    this.artifacts.set(newArtifactId, newArtifact);

    // Track in version history
    const rootId = existing.previousVersionId || existing.artifactId;
    const lineage = this.versions.get(rootId) || [];
    lineage.push({ ...newArtifact });
    this.versions.set(rootId, lineage);
    this.versions.set(newArtifactId, lineage);

    return newArtifact;
  }

  /**
   * Commits formal verification record onto an artifact.
   */
  public verifyArtifact(
    artifactId: string,
    organizationId: string,
    verification: {
      verified: boolean;
      verifier: string;
      checks: string[];
      technicalPassed?: boolean;
      businessPassed?: boolean;
    }
  ): WorkforceArtifact {
    const artifact = this.getArtifact(artifactId, organizationId);
    if (!artifact) {
      throw new Error(`Artifact "${artifactId}" not found or unauthorized.`);
    }

    artifact.verification = {
      verified: verification.verified,
      verifier: verification.verifier,
      timestamp: Date.now(),
      checks: verification.checks,
      technicalPassed: verification.technicalPassed,
      businessPassed: verification.businessPassed,
    };
    artifact.status = verification.verified ? "VERIFIED" : "REJECTED";
    artifact.updatedAt = Date.now();

    return artifact;
  }

  /**
   * Retrieves an artifact strictly scoped to an organization.
   */
  public getArtifact(artifactId: string, organizationId: string): WorkforceArtifact | undefined {
    const artifact = this.artifacts.get(artifactId);
    if (!artifact) return undefined;
    if (artifact.organizationId !== organizationId) {
      // Cross-tenant access strictly blocked
      return undefined;
    }
    return artifact;
  }

  /**
   * Lists artifacts for an organization with optional filters.
   */
  public listArtifacts(
    organizationId: string,
    filters?: {
      artifactType?: ArtifactType;
      sourceWorker?: string;
      status?: ArtifactStatus;
    }
  ): WorkforceArtifact[] {
    const results: WorkforceArtifact[] = [];

    for (const art of this.artifacts.values()) {
      if (art.organizationId !== organizationId) continue;
      if (filters?.artifactType && art.artifactType !== filters.artifactType) continue;
      if (filters?.sourceWorker && art.sourceWorker !== filters.sourceWorker) continue;
      if (filters?.status && art.status !== filters.status) continue;
      results.push(art);
    }

    return results.sort((a, b) => b.createdAt - a.createdAt);
  }

  /**
   * Retrieves full version history lineage of an artifact.
   */
  public getArtifactHistory(artifactId: string, organizationId: string): WorkforceArtifact[] {
    const art = this.getArtifact(artifactId, organizationId);
    if (!art) return [];
    const rootId = art.previousVersionId || art.artifactId;
    const lineage = this.versions.get(rootId) || [art];
    return lineage.filter((item) => item.organizationId === organizationId);
  }
}
